CREATE TABLE bad_type (id pg_catalog.text GENERATED ALWAYS AS IDENTITY);
ALTER TABLE t ADD COLUMN id bigint NULL GENERATED ALWAYS AS IDENTITY;
CREATE TABLE bad_default (a int DEFAULT 0 GENERATED ALWAYS AS (1) STORED);
CREATE TABLE bad_increment (id bigint GENERATED ALWAYS AS IDENTITY (INCREMENT 0));
CREATE TABLE bad_cache (id bigint GENERATED ALWAYS AS IDENTITY (CACHE 0));
CREATE TABLE bad_bounds (id smallint GENERATED ALWAYS AS IDENTITY (MAXVALUE 32768));
CREATE TABLE bad_start (id bigint GENERATED ALWAYS AS IDENTITY (START 0));
